const prisma = require('../config/prisma.js');

const MAX_TITLE_LENGTH = 60;

// Derived from the first question rather than generated by the model - it is
// instant, free, and predictable.
function titleFrom(question) {
    const flat = question.trim().replace(/\s+/g, ' ');
    return flat.length <= MAX_TITLE_LENGTH
        ? flat
        : `${flat.slice(0, MAX_TITLE_LENGTH).trimEnd()}…`;
}

const listConversations = async (req, res) => {
    try {
        const conversations = await prisma.conversation.findMany({
            where: { userId: req.user.id },
            orderBy: { updatedAt: 'desc' },
            take: 50,
            select: {
                id: true,
                title: true,
                documentId: true,
                collectionId: true,
                updatedAt: true,
                _count: { select: { queries: true } },
            },
        });

        res.status(200).json({ success: true, conversations });
    } catch (error) {
        console.error('Error listing conversations:', error);
        res.status(500).json({ success: false, message: 'Failed to list conversations' });
    }
};

// GET /conversations/:id - the full thread, so reopening it restores the
// messages and their source cards.
const getConversation = async (req, res) => {
    try {
        const conversation = await prisma.conversation.findFirst({
            where: { id: req.params.id, userId: req.user.id },
            include: {
                queries: {
                    orderBy: { createdAt: 'asc' },
                    select: {
                        id: true,
                        question: true,
                        answer: true,
                        sources: true,
                        responseMs: true,
                        createdAt: true,
                    },
                },
            },
        });

        if (!conversation) {
            return res.status(404).json({ success: false, message: 'Conversation not found' });
        }

        res.status(200).json({ success: true, conversation });
    } catch (error) {
        console.error('Error fetching conversation:', error);
        res.status(500).json({ success: false, message: 'Failed to fetch conversation' });
    }
};

const deleteConversation = async (req, res) => {
    try {
        const conversation = await prisma.conversation.findFirst({
            where: { id: req.params.id, userId: req.user.id },
        });

        if (!conversation) {
            return res.status(404).json({ success: false, message: 'Conversation not found' });
        }

        // Queries cascade with the conversation.
        await prisma.conversation.delete({ where: { id: conversation.id } });

        res.status(200).json({ success: true, message: 'Conversation deleted' });
    } catch (error) {
        console.error('Error deleting conversation:', error);
        res.status(500).json({ success: false, message: 'Failed to delete conversation' });
    }
};

module.exports = {
    listConversations,
    getConversation,
    deleteConversation,
    titleFrom,
};
